    private static readonly ConditionalWeakTable<Geometry, object> _rtlBehaviors = [];

    /// <summary>The RTL behavior declared with the geometry, applied by <see cref="BaseIcon"/>.</summary>
    public static RtlBehavior GetRtlBehavior(Geometry geometry)
        => _rtlBehaviors.TryGetValue(geometry, out var behavior) ? (RtlBehavior)behavior : RtlBehavior.None;

    private static Geometry Parse(string data, RtlBehavior rtlBehavior)
    {
        var geometry = Geometry.Parse(data);
        _rtlBehaviors.Add(geometry, rtlBehavior);

        return geometry;
    }

